#!/usr/bin/env python3
"""Generate the recursive command-line reference from ``build_parser``.

Run from the repository root:

    pixi run cli-reference
    pixi run cli-reference-check
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "src"
OUTPUT = ROOT / "docs" / "reference" / "cli.md"
HEADER = (
    "<!-- Generated by scripts/gen_cli_reference.py; edit the CLI parsers instead. -->"
)


def command_parsers(
    parser: argparse.ArgumentParser,
) -> list[tuple[tuple[str, ...], argparse.ArgumentParser]]:
    """Return every public parser path in deterministic depth-first order."""
    commands = [(tuple(parser.prog.split()), parser)]
    for action in parser._actions:
        if not isinstance(action, argparse._SubParsersAction):
            continue
        for name, child in action.choices.items():
            if name.startswith("_"):
                continue
            commands.extend(command_parsers(child))
    return commands


def generate() -> str:
    if str(SRC) not in sys.path:
        sys.path.insert(0, str(SRC))
    from torchsky.cli import build_parser

    lines = [
        HEADER,
        "",
        "# CLI reference",
        "",
        "This page is generated recursively from the installed `torchsky` argument parser.",
        "",
    ]
    for path, parser in command_parsers(build_parser()):
        command = " ".join(path)
        help_text = parser.format_help().rstrip()
        if not help_text:
            raise SystemExit(f"empty public help for {command}")
        lines.extend([f"## `{command}`", "", "```text", help_text, "```", ""])
    return "\n".join(lines).rstrip() + "\n"


def check(content: str) -> int:
    if not OUTPUT.is_file():
        print(f"missing generated page: {OUTPUT.relative_to(ROOT)}")
        return 1
    if OUTPUT.read_text(encoding="utf-8") != content:
        print(f"stale generated page: {OUTPUT.relative_to(ROOT)}")
        print("Run `pixi run cli-reference` and re-check.")
        return 1
    print(f"CLI reference is current: {OUTPUT.relative_to(ROOT)}")
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument(
        "--write", action="store_true", help="Regenerate the CLI reference"
    )
    mode.add_argument(
        "--check", action="store_true", help="Fail if the CLI reference is stale"
    )
    args = parser.parse_args(argv)

    content = generate()
    if args.check:
        return check(content)
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(content, encoding="utf-8")
    print(f"wrote CLI reference to {OUTPUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
